const pairs = Object.entries(COPY).map(([left, right]) =>
    /[ぁ-んァ-ヶ一-龠]/u.test(left) ? [left, right] : [right, left]);
const japanese = new Map(pairs.map(([ja, en]) => [en, ja]));
const english = new Map(pairs);

export function resolveLanguage(saved, languages = []) {
    if (saved === "ja" || saved === "en") return saved;
    return /^ja(?:-|$)/i.test(languages[0] ?? "") ? "ja" : "en";
}

export function translate(text, language) {
    const dictionary = language === "ja" ? japanese : english;
    if (dictionary.has(text)) return dictionary.get(text);
    const guests = text.match(/^(?:ゲスト旋律|Guest melody) × (\d+)$/u);
    if (guests) return `${language === "ja" ? "ゲスト旋律" : "Guest melody"} × ${guests[1]}`;
    const instruments = text.match(/^(?:楽器|Instruments): (.+)$/u);
    if (instruments) return `${language === "ja" ? "楽器" : "Instruments"}: ${instruments[1].split(" / ").map(part => translate(part, language)).join(" / ")}`;
    const loadError = text.match(/^(?:Cannot load preferences: |設定を読み込めません: )(.+)$/u);
    if (loadError) return `${language === "ja" ? "設定を読み込めません: " : "Cannot load preferences: "}${loadError[1]}`;
    return text;
}

export function translateDocument(root, language) {
    const walker = root.ownerDocument.createTreeWalker(root, 4);
    let node;
    while ((node = walker.nextNode())) {
        if (node.parentElement.closest("script, style, #pattern, #reason, #language")) continue;
        const content = node.textContent.trim();
        const translated = translate(content, language);
        if (content !== translated) node.textContent = node.textContent.replace(content, translated);
    }
}
